# Generated by build.py from recipe.yml for recipe smtp-send-to-several-recipients. Do not edit.
set -e
cd "$(dirname "$0")"
cat > notice.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Maintenance on Saturday

The system is down from 02:00 to 04:00.
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox cy@example.com:cypass --mailbox dee@example.com:deepass --mailbox fay@example.com:faypass --mailbox gus@example.com:guspass --mailbox hal@example.com:halpass --mailbox ivy@example.com:ivypass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com --mail-rcpt bob@example.com --mail-rcpt cy@example.com -T notice.eml smtp://127.0.0.1:8080/example.com --next -sS --retry 10 --retry-all-errors --retry-delay 1 -o /dev/null -u cy@example.com:cypass "imap://127.0.0.1:8081/INBOX;UID=1" --next -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?ALL" --next -sS -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX?ALL" --next -sS -u cy@example.com:cypass "imap://127.0.0.1:8081/INBOX?ALL"
kill $(jobs -p)
